#include "../Source/DelayEngine.h"
#include <iostream>
#include <stdexcept>
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
int main(){try{for(int mode=0;mode<4;++mode){std::vector<float> result[2];double energy[2]={};for(int endpoint=0;endpoint<2;++endpoint){fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.timeMs=20;s.feedback=0;s.mix=1;s.hp=20;s.lp=20000;s.duck=s.diffusion=0;s.mode=mode;s.analog=float(endpoint);std::vector<float> l(48000),r(l.size());for(size_t i=0;i<l.size();++i)l[i]=r[i]=.3f*std::sin(float(i)*6.2831853f*400/48000)+.15f*std::sin(float(i)*6.2831853f*8000/48000);e.process(l.data(),r.data(),int(l.size()),s);for(size_t i=4800;i<l.size();++i){check(std::isfinite(l[i])&&std::abs(l[i])<1,"analog must remain finite and bounded");energy[endpoint]+=l[i]*l[i];}result[endpoint]=std::move(l);}double difference=0;for(size_t i=4800;i<result[0].size();++i)difference+=std::pow(result[0][i]-result[1][i],2);if(mode==0)check(difference<1e-8,"Clean must ignore analog coloration");else check(difference>1,"colored character analog endpoints must differ");check(energy[1]>.1&&energy[0]>.1,"analog must not mute wet signal");}
 // Crossfaded fixed taps must not create a large sample discontinuity during time changes.
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.timeMs=100;s.mode=0;s.analog=s.feedback=s.duck=s.diffusion=0;s.mix=1;s.hp=20;s.lp=20000;float l[256],r[256];float prev=0,maxStep=0;for(int block=0;block<300;++block){if(block==100)s.timeMs=37;for(int i=0;i<256;++i)l[i]=r[i]=.25f*std::sin(float(block*256+i)*6.2831853f*200/48000);e.process(l,r,256,s);for(int i=0;i<256;++i){if(block>90&&block<130)maxStep=std::max(maxStep,std::abs(l[i]-prev));prev=l[i];}}check(maxStep<.03f,"delay time crossfade must be smooth");}
 // Closing capture must leave a real audio tail; mouse release does not alter the latched parameter.
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.timeMs=100;s.mode=0;s.analog=s.duck=s.diffusion=0;s.mix=1;s.feedback=.5f;s.throwMode=true;s.trigger=true;std::vector<float> l(24000),r(l.size());for(int i=0;i<317;++i)l[i]=r[i]=.2f;e.process(l.data(),r.data(),317,s);s.trigger=false;std::fill(l.begin(),l.end(),0);std::fill(r.begin(),r.end(),0);e.process(l.data(),r.data(),int(l.size()),s);double tail=0;for(int i=4000;i<16000;++i)tail+=l[i]*l[i]+r[i]*r[i];check(tail>.01,"stopping throw capture must preserve echoes");}
 std::cout<<"PASS: Analog changes every mode; smooth fixed-tap time transitions; throw tail retained\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
